import type { MeaningPack } from '../../types';

export const enSmv1: MeaningPack = {
  lang: 'en',
  texts: {
    'sumadhva-vijaya-01': {
      verses: {
        '0.0': 'I bow to Nārāyaṇa, the beloved, the one abode of all auspicious qualities, radiant like the newly risen sun, the cause of all, the lord of Śrī and of Prāṇa (Vāyu).',
        '0.1': 'Salutations to Kṛṣṇa, dark-blue like a rain cloud, dear to the husband of Kṛṣṇā (Bhīma), under whose care Gokula, ever untroubled and pure-hearted, flourished.',
        '0.2': 'May the fame of Madhva grant us clear vision — that fame which shines even beyond the three worlds, again and again removes inner darkness, and outshines the brilliance of the sun.',
        '0.3': 'I bow to those excellent teachers, the revered Trivikrama (the poet\'s father), from whose moon-like face came rays — his words — shaped like lamps of truth, by which the world\'s darkness was dispelled and it attained bliss.',
        '0.4': 'For devotion to Mukunda, which is born of devotion to the guru, and for the unbroken grace of the good, I shall narrate the weighty and pure sport of the incarnations of Vāyu, the teacher of the world.',
        '0.5': 'That sport is fit to be praised by the syllables of the Vedic mantras; even Śiva, Indra and others long to tell it. As I, of slow mind, try to tell it in brief words, may the virtuous be kind to me.',
        '0.6': 'All activities, high and low, happen through him (Vāyu, the life-breath of all); so what wonder is there in telling of his deeds? Yet retelling the deeds of the crown-jewels among the renowned purifies the mind.',
        '0.7': 'I am a garland-maker stringing the gems of his deeds, eager but without fine sight; if I set things before and after out of order, or make any other slip, may the great forgive me again and again.',
        '0.8': 'Honouring the command of Śrī\'s Lord and the request of the gods led by Indra — the most fitting thing in the three worlds — the lord of the vital breaths, guide of all beings and teacher of the good, was born in the house of Kesarī.',
        '0.9': 'Whatever virtues are famed in the world, people point to him as the example of each; this glorious one, the very foremost of great devotees, they call Hanumān.',
        '0.10': 'Performing most wondrous deeds, praised in the assemblies of the gods, he beheld the Lord of Ramā in the form of Rāma, friend of Sugrīva, who purifies the world.',
        '0.11': 'Then the chief of the monkeys, driven by the weight of great devotion, bowed at his lotus feet, and the Primeval Person embraced him with his two arms, lovely as the heart of a lotus.',
        '0.12': 'The slayer of Madhu (Rāma) — who split the row of unsplittable sāla trees, killed Indra\'s son (Vālin) and gave great joy to the Sun\'s son (Sugrīva) — then sent the hero forth on his mission.',
        '0.13': 'Released by Rāma — skilled in battle, who draws to the ear and prizes virtue (also: the bowstring) — he sped forth like a foremost arrow, terrifying to enemies and taking the side of the good (also: well-feathered).',
        '0.14': 'Ah, this Hanumān was like a fresh rain cloud: he gladdened Sītā with his words (as a cloud with its waters), burned the host of flesh-eating rākṣasas with his own fire (as lightning burns trees), crossed the ocean, and bowed at Viṣṇu\'s feet (as a cloud rests in the sky).',
        '0.15': 'A wingless being in the three worlds (also: impartial), who takes no pleasures (also: does not eat serpents), he carried Rāma, the bearer of the universe, and outdid Garuḍa, king of birds, in swift exploits — a wonder indeed.',
        '0.16': 'When the banner of the Raghu line had built the bridge across the ocean, which trembled at the mere knitting of his brow, Hanumān gave the ten-headed Rāvaṇa a blow of his fist — the fitting reply to his threats against Sītā.',
        '0.17': 'In the sacrifice of battle, where the blazing, brilliant Rāghava was the sacred fire and Sugrīva the sacrificer, he performed the office of the adhvaryu priest, with Lakṣmaṇa, son of Sumitrā, as his assistant priest.',
        '0.18': 'Carrying a flower for Rāma\'s worship he took care to use both hands; but carrying with one arm the great mountain that held the Sañjīvanī and other herbs, he made no effort at all.',
        '0.19': 'He served the Supreme Person, slayer of foes, now united with the king\'s daughter Sītā — whose purity had been shown by her entry into fire — as though adorned with a golden garland.',
        '0.20': 'For a long time he served with his eyes the form of the Lord of Ayodhyā, which brings blessing to the world: dark, smiling, long- and broad-armed, lotus-eyed, with the gait of a royal elephant.',
        '0.21': 'When the coronation was complete, Sītā, at Rāma\'s word — "Give it to the one dearest to us among our devotees" — bound her long compassion on him under the guise of a lovely jewelled necklace.',
        '0.22': 'Placing on his head a hand full of deep affection, with eyes moist with compassion and words like nectar, the Lord, pleased with his service, granted him a share in his own enjoyments.',
        '0.23': 'No one was dearer to Rāma than he, and nothing was hard to obtain in Rāma\'s kingdom; yet, delighting only in serving his feet, he did not desire enjoyments — that is true detachment.',
        '0.24': '"Salutations, salutations, O Lord, salutations to you! Salutations, salutations, O Rāma, salutations to you! Again and again I bow to your lotus feet, O Lord!" — bowing thus, he rejoiced.',
        '0.25': 'How can we describe the supreme grace of Sītā\'s Lord toward that foremost of monkeys? When he left the earth, he gave him his very self, for eternal service.',
        '0.26': 'Ever immersed in the nectar of Rāma\'s story, the source of bliss to devotees, he dwells even now in Kimpuruṣa, serving Rāma his master.',
        '0.27': 'The good declare Bhīma to be the second incarnation of that same Vāyu; Kuntī, queen of King Pāṇḍu, bore him here by the mere touch of the loving Wind god.',
        '0.28': 'Long ago Indra\'s thunderbolt, hurled by Indra\'s hand, only cut off the mountains\' wings; but — a wonder — this infant, slipping from his mother\'s hand, shattered a mountain\'s body by the mere contact of his limbs.',
        '0.29': 'Seeing the princes\' languid games in the city, he, finding play there dull, longed for and remembered his boyhood sport in the forest, where whole troops of lions were slain.',
        '0.30': 'He ate and digested the poison his enemy gave him, so that even the serpents\' venom lost heart; and he came back with ease from Pramāṇakoṭi. This is no wonder in him who gives life to the world.',
        '0.31': 'As a yogi burns the body by the power of yoga and goes forth bearing his virtues to reach Nārāyaṇa, so he burned the lac house, came out carrying his brothers, and, honoured by the world, reached Nārāyaṇa in the form of Vyāsa.',
        '0.32': 'The accomplished one, pure in mind, offered to Vyāsa, the Infinite, all the good deeds he had done so far, and resolved that whatever he would do thereafter would be his worship.',
        '0.33': 'Then this royal swan — who drove off the heron (Baka) that haunted Viṣṇu\'s sky, who scattered the other birds (his foes), and who was well-winged (rich in allies) — together with his brothers won the princess Draupadī, as a royal swan wins its mate.',
        '0.34': 'Bhīma long rejoiced in Mukunda, his beloved cousin (son of his mother\'s brother), whose beauty surpassed the splendour of the blue lotus, whose moon-face smiled, and whose eyes were long like lotus petals.',
        '0.35': 'The hero swiftly cast down Jarāsandha, son of Bṛhadratha, mighty with the mace and fierce in battle, and together with Govinda and Indra\'s son Arjuna had King Yudhiṣṭhira perform a brilliant Rājasūya sacrifice.',
        '0.36': 'Burning to slay the enemy, the fierce Bhīma gathered up his beloved Draupadī\'s fine, curling black hair, dishevelled by Duḥśāsana, as if gathering black serpents.',
        '0.37': 'As the fire that was Vṛkodara blazed fiercely from forest to forest, eager to burn up the cruel host of kings, the creatures that terrified men perished in its intense heat.',
        '0.38': 'On the king of mountains he slew many fierce Krodhavaśa demons led by Maṇimān — huge-bodied, red-eyed, double-tongued like serpents, roaming here and there.',
        '0.39': 'Then this splendid son of Vāyu, hidden in another guise like fire in ashes, in due course reduced to ashes the whole host of Kīcakas — noisy and fierce, who had blocked every quarter (like hollow reeds whistling in the wind).',
        '0.40': 'Like a fire whose track is black, he — following Kṛṣṇa\'s path and joined with Vijaya (Arjuna; also: victory), ever bearing great weapons (also: flames), unassailable — shone as he consumed the enemy forest made terrible by Bhīṣma, Droṇa and others.',
        '0.41': 'Destroying all the sons of Dhṛtarāṣṭra — mighty, rising up, rash, fiercely wrathful, their wings burned (their allies destroyed) — he, sporting with many weapons, shone with supreme glory.',
        '0.42': 'King of bees at Kṛṣṇa\'s lotus feet, king of swans at the lotus of Kṛṣṇā\'s (Draupadī\'s) face, the sun to the rows of lotuses that are the people — the king of heroes shone with his brothers.',
        '0.43': 'Placing the earth in the care of Parīkṣit, grandson of his brother Arjuna, leaving torment in the minds of the demons, fame in the three worlds, and Mukunda in his heart, Bhīma with his brothers attained his own abode.',
        '0.44': 'Thus destroyed by the terrible blows of Vāyu, who serves at Viṣṇu\'s feet, those enemies of the gods — like clouds scattered by the wind, robbed of their substance and wavering in conduct — lost all their lustre.',
        '0.45': 'Wishing to take revenge for this, their strength gone and finding themselves in such distress, they in time — in the Kali age — devised a doctrine fit for their own nature: that Mukunda is without qualities.',
        '0.46': '(The poet\'s polemic begins.) Maṇimān, full of enmity, who had been slain earlier by Bhīma — eloquent, ambitious, and having won Śiva\'s favour — was born on earth as one called Saṅkara ("the confounder"); other demon chiefs too were born here to rival (the gods).',
        '0.47': 'Like a cat with no understanding seizing the sacrificial oblation, a dog that craves worthless things seizing the sacred cake, or a restless monkey seizing a jewelled garland, this wicked one laid hold of the Veda and the other scriptures.',
        '0.48': 'Thinking "otherwise people will not bow to me," the crafty one took up the fourth stage of life, sannyāsa — as an untamable rogue elephant enters a clear lotus pond wishing to muddy it.',
        '0.49': 'Seeing that the non-Vedic Mādhyamika (Buddhist) doctrine had been refuted, he, a partisan of that side, set forth here a path suited to upholding that same position.',
        '0.50': 'Where the Buddhist said "non-being," he spoke of māyā, distinct from both being and non-being, giving the Buddhist "concealment" (saṃvṛti) the name māyā; and to establish the void he called Brahman undifferentiated — hence, the poet says, he is known as a crypto-Buddhist.',
        '0.51': 'Because he stole away the steed that is the whole body of the Vedas, and the sun that is the host of Brahma-sūtras which illumines everything with its rays (words), they call him the great thief.',
        '0.52': 'He spoke against the very sūtras Vyāsa composed, yet said "I am their commentator"; that Vyāsa did not burn him up on the spot shows that the Lord in Vyāsa\'s form is an ocean of forbearance.',
        '0.53': 'The host of radiant jewel-lamps that are the Vedas had their light hidden under the mire of his vast verbiage; becoming a mine of confusion (saṅkaratā) for the unlearned, he came, it is said, to be known as "Saṅkara."',
        '0.54': '"The world is unreal; the Lord has no qualities; there is no difference between selves" — thus the demons spread their teaching far and wide in every quarter, and Vāsudeva, full of hosts of great qualities such as bliss, alas, slowly became hidden even in the minds of the good.',
        '0.55': 'Thus ends the first canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-02': {
      verses: {
        '0.0': 'When the sun of true knowledge had set by the force of time, and people, blinded by the spreading thick darkness of wrong commentaries, were slipping from the path of the good, the gods led by four-faced Brahmā, weary at heart, took refuge in Mukunda.',
        '0.1': 'The Lord, called "Triyuga" because he appears openly only in three ages, did not wish to incarnate in Kali, nor to command Brahmā, who has no incarnations; seeing no other all-knowing one equal to the task, he spoke with a smile to Vāyu, the life of the world.',
        '0.2': '"The divine souls, pained and distressed as they search for the path of Vedānta, are without refuge and deserve our compassion. O fair-faced one, take another form, adorn a part of the earth, and gladden them by establishing my good qualities."',
        '0.3': 'With joined palms Vāyu bore this command on his head like a priceless, brilliant crown-jewel; bearing the gods\' request in his heart like a necklace, and wishing to favour his own devotees, he resolved to descend.',
        '0.4': 'That very time arrived when the many families of the good grew anxious: "We do not know the true essence of the Vedānta\'s settled conclusion; alas, how shall we attain the highest good?"',
        '0.5': 'To comfort them and announce the good news, the Lord who dwells at Rajatapīṭhapura (Uḍupi) entered into a man, when a great crowd had gathered with eager clamour for a grand festival.',
        '0.6': 'Possessing a man who by nature had no such skill, and so convincing his people, he danced vigorously on the top of a tall flag-staff, striking poses like an actor on the stage, a wonder to all.',
        '0.7': 'Addressing the people there with his arm raised, he loudly declared under oath: "Soon there will be born here in the world the all-knowing Lord, whose conduct will be for the good of all."',
        '0.8': 'On this earth with its seven oceans and continents, in Bhārata, the land of action, in the Kali age, there lived a brāhmaṇa born of a very pure lineage, the crown-jewel of the noble Madhyageha family.',
        '0.9': 'His ancestral home was the village called Śivarūpya (Śivaḷḷi), rich in virtue, splendidly adorned by the Lords of Vedādri and of holy Rajatapīṭhapura, and shining like Ilāvṛta made bright by the lord of the golden mountain Meru.',
        '0.10': 'That sole banner of three families lived at the holy place called Pājaka, graced by a hill crowned with the shining shrine of Durgā, Hari\'s sister, installed by Paraśurāma; it is called Pājaka because it ever holds bliss (ka) through protecting (pāja) the world.',
        '0.11': 'He took as his wife a maiden of fitting form, given by an excellent brāhmaṇa, worthy to bestow a peerless treasure that serves the goals of life — like Vedic learning itself, shining with fair syllables (also: with golden beauty).',
        '0.12': 'That chief of brāhmaṇas delighted in her, who brought him unbroken joy — as a man of great discernment delights in a clear Upaniṣad, one of pure senses in devotion, and one free of false pride in supreme liberation.',
        '0.13': 'Devoted to his own dharma, the steadfast man bound his devotion to the feet of that Lord, his family deity; people call this humble man, who knew the deep secrets of the Mahābhārata and the Purāṇas, "Bhaṭṭa."',
        '0.14': 'With the nectar of Govinda\'s lovely stories he delighted not only the senses of men but also those of the gods who worship the lotus feet of Śrī\'s Lord at Rajatapīṭhapura.',
        '0.15': 'Though well satisfied by the nectar of Hari\'s qualities, yet seeing people insistent on the doctrine that God has no qualities, and his own mind made doubtful about the truth by the times, the wise man reflected with an intellect purified by hearing the scriptures.',
        '0.16': '"The one who saves from the hell called \'put\' is named putra, a son; real protection is not easily had from an imperfect man. By what means, then, may we obtain a faultless son who knows all, the very form of a treasury of learning?"',
        '0.17': '"Of old, Kardama, Parāśara, Pāṇḍu and others obtained virtuous offspring by serving Him; let us take refuge in Nārāyaṇa, our family\'s Lord, whose body is full of all good qualities, an ocean of the nectar of compassion."',
        '0.18': 'Reflecting thus, that pure soul, who had no other kin, worshipped with devotion for twelve years the Lord who dwells at Rajatapīṭhapura, reclining on the serpent — the one to be meditated on, giver of what is dearest, who breaks the fear of the ocean of saṃsāra.',
        '0.19': 'Worshipping the Lord\'s lotus feet together with his wife, he made his already slight enjoyments slighter still; he further subdued a heart already self-controlled, and made his clean body purer still.',
        '0.20': 'With severe vows such as living on milk alone and many other excellent observances, husband and wife, longing for a son who would be an ocean of virtues, greatly pleased the Perfect Person — like Aditi and Kaśyapa of old, urged on by the gods.',
        '0.21': 'Bathed in the nectar of the Lord\'s great compassion, their slender frames nourished by the grace of Śrī and Śrīdhara, and glowing with a divine lustre born of their many vows, they then attained purity of body and mind.',
        '0.22': 'Then, at the proper season, honoured by her husband, the brāhmaṇa\'s daughter conceived for the happiness of the worlds — like a night with a clear sky, filling the quarters with hope, that carries within it the coming moon of the bright fortnight, destined to dispel darkness.',
        '0.23': 'Before the brāhmaṇa\'s wife gave birth to him — growing like the moon\'s disc in the bright fortnight — Vāyu, descending with a portion of himself, bowed to Viṣṇu at Rūpyapīṭha (Uḍupi) and went to their home.',
        '0.24': 'As a king enters a fine city, the Lord of the worlds entered that most beautiful dwelling — the body, perfect in all its marks, with its nine shining gates — driving out any other that might be there.',
        '0.25': '"Let all the good rejoice and the wicked be downcast; this Vāyu has appeared on earth!" — as if proclaiming this, the deep sound of the gods\' drums was heard here even by wondering men.',
        '0.26': 'The wise father, returning near home after worshipping the Lord, heard first the drums sounding as for a festival and then the news of his son\'s birth; he felt great joy, and an intimation — though not yet direct — that his heart\'s wish had been fulfilled.',
        '0.27': 'Entering the house, rejoicing again and again in his moon-faced son and bowing to Mukunda\'s grace, the father, doer of good rites, performed the birth ceremony and the other rites for the newborn, who bore a host of virtues.',
        '0.28': 'Since this lord of the life-breath (asu-deva) was born for the sake of knowledge, and was ever devoted to Vāsudeva\'s feet, the gods proclaimed the name "Vāsudeva" — the very name his father gave him at the naming.',
        '0.29': 'A man of the Pūrvālaya family who gave a cow so that the infant might have milk was later born as his own son\'s son and gained knowledge of the Supreme Self that leads to liberation; a gift surely bears fruit according to the worth of its recipient.',
        '0.30': 'Once a wise kinsman took up that jewel of a son — never afraid, eyes always wide open, his lustre mocking the new moon, priceless in the world — and offered him as a gift to his own Master, the Lord at Uḍupi.',
        '0.31': 'Bowing to Hari who dwells at Rajatapīṭhapura and praying that the child might prosper free of mishap, he set out with the boy and their attendants at midnight for home.',
        '0.32': 'In a fearsome forest, a spirit whose haunt it was struck one of those travelling at night with the child; seeing him vomit blood, someone asked, "Strange — how is it that this spirit, which preys on children, has done this and left the child alone?"',
        '0.33': 'The great spirit, possessing a man, said: "I am well able to kill all who come here at the hour of our roaming, if they lack the protection of His power; but He, the Lord of the world, is only seemingly a little child!"',
        '0.34': 'Once, after nursing the child well, the mother had to leave the house, though she could hardly bear to be apart; timid as she was, she left the protector of the universe in the care of her own daughter — to protect Him who protects all!',
        '0.35': 'Trying to soothe the crying baby, the innocent girl coaxed him with sweet, childish words: "Don\'t cry any more, darling, dear little fair-face; mother will soon bring you what you like."',
        '0.36': 'When the baby kept crying again and again and the mother had still not come after a long time, the girl took him up and kept looking down the road for her mother, again and again.',
        '0.37': 'At her wits\' end, she made up her mind and fed him a whole heap of well-cooked horse-gram, giving him cold water to drink as well — horse-gram whose heating effect the mother greatly dreaded.',
        '0.38': '"Surely the child is thirsty and crying hard — shame on me, heartless, busy with others\' work!" Thus anxious, the brāhmaṇa\'s wife came home, and found her son cheerful, with a full belly.',
        '0.39': 'Asking, she learned all that had happened; thinking, "The baby has eaten what even youths can hardly digest," she scolded her daughter severely — frightened at first, then angry, then sorry at heart.',
        '0.40': 'When her son stayed as healthy as before, his mother was amazed — he whose true mother, Lakṣmī, mother of the three worlds, was not amazed even when he drank poison (the Hālāhala), for he is all-powerful.',
        '0.41': 'His mother would take him and nurse him again and again; his father would hold him and recite prayers for his welfare; others too fondled him — but everyone longed for the elixir of his smiling face.',
        '0.42': 'His speech, at first indistinct in his mouth, played there as if shy — speech honoured by the world, lovingly cherished by the gods and the good, and graceful in its steps (words) like the goddess Bhāratī herself.',
        '0.43': 'He crawled, then stood by himself, and later, by practice, gradually walked; yet since every movement in the world happens by his grace, all this was but play-acting on the part of Vāyu.',
        '0.44': 'Once, holding the clean tip of the tail of his favourite bull as it left the pen in the morning, he suddenly went off, unseen by his family, with the bull as it grazed through various woods.',
        '0.45': 'Clinging to one part of that huge bull — with lofty, gleaming horns and hooves that covered the ground — the child shone like the morning sun on the eastern mountain (whose peaks, base and caves the bull\'s features recall).',
        '0.46': '"Is the child playing? Has he gone into some other house? Has he, being so self-willed, fallen into a well?" Thinking thus, his people searched again and again, and, alas, not finding him, were stricken with anguish.',
        '0.47': 'That evening people saw the one-year-old child coming home holding on to the young bull — confirming what the forest-folk had reported about the infant clinging to it.',
        '0.48': 'As a pauper recovers the wish-granting gem, or a seeker of liberation the path of knowledge centred on Viṣṇu, so his family, regaining their lost son, regarded it as the Lord\'s own grace.',
        '0.49': 'Once, when the boy had finished playing and was urging his father to eat, the father, looking at his son\'s moon-face, said softly: "This creditor, who sold us the bull, is holding us back."',
        '0.50': 'Smiling, the child at once gave the creditor, with his soft playful hand, a few seeds in place of the coins he wanted; and the creditor accepted them with great respect.',
        '0.51': '"I have been paid by your son," he said, and even when later the brāhmaṇa wished to repay him from his own wealth, he would not take it; through those seeds, from a superhuman being in a child\'s new form, he had gained a far higher goal of life — how wonderful!',
        '0.52': 'The people rejoiced in that child of many sports, a true portion of the deity of breath, bearing the holy name Vāsudeva — as though he were Vāsudeva himself.',
        '0.53': 'Thus, as Viṣṇu\'s servant played on earth, though hidden, the hearts of good people filled with joy; for when the sun rises, even if veiled by a bank of clouds, the lotuses of people\'s eyes surely open.',
        '0.54': 'Thus ends the second canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-03': {
      verses: {
        '0.0': 'Once the couple — dear to people whose eyes were fixed on the smiling moon-face of their lovely son — went happily with their kinsfolk to a festival, to gladden their relatives.',
        '0.1': 'Amid the bustle of kinsfolk coming and going, meeting and exchanging greetings, the boy, unnoticed by his mother, slipped away from that noisy shelter along with some travellers.',
        '0.2': '"Where do you want to go, child? It is not right for you to leave your people now," the travellers said; the Lord, walking on, gave a calm, smiling reply.',
        '0.3': 'Hurrying on, he bowed to the Lord of Ramā in the shrine of the forest deity there; and going on from there, he bowed to Him also in the temple of a place named after the "little coconut."',
        '0.4': 'His radiant eyes wide with the joy of beholding the lotus-navelled Lord, he — the sun to the lotuses of people\'s hearts and eyes — went on to Rajatapīṭhapura (Uḍupi).',
        '0.5': '"These well-made salutations to Hari surpass a host of horse-sacrifices" — so it seemed as he bowed there, watched in wonder by the gods and by the gatherings of brāhmaṇas.',
        '0.6': 'There is no moment when he does not bow to Hari, behold Him and praise Him; yet by doing so here in a special way, he was teaching good people.',
        '0.7': 'Not seeing his son, the loving father, best of brāhmaṇas, searched for him, hurrying along road after road on his trail and asking people again and again which way he had gone.',
        '0.8': 'Following step by step the path that people (and the ever-moving wind) pointed out, with intense longing, the brāhmaṇa, like a great bee, found the lovely, smiling lotus of his son\'s face.',
        '0.9': 'He had held back the tears that rose to his eyes in the pain of separation; now, holding back even the tears of joy, the father spoke.',
        '0.10': '"Son, tell me truly: you have come all the way here now, but who was your companion on this very long road, child, with none of your people?"',
        '0.11': 'Hearing his father\'s words, the lotus-eyed boy sweetly replied: "As I came along to my own place, and as I kept going from there, the Lord of the forest-shrine was my friend."',
        '0.12': '"When I came on from that other shrine, where I had bowed, Hari there was my friend. Here too I bowed to the Lord in the temple on the eastern side, and then to the Supreme Lord himself."',
        '0.13': '"Then, coming here with Him, I bowed to the Lord who abides here." Saying this, the child shone, honoured by the astonished gathering.',
        '0.14': 'The brāhmaṇa bowed and prayed: "O abode of compassion, protect this child of mine, whose merit is small — a child who loves your feet and wandered without his people on a road haunted by many fearsome spirits."',
        '0.15': 'Embracing his son, the father, rich in austerity, went home with his wife; and as this young sun rose, the lotus faces of the good broke into smiles.',
        '0.16': 'On the hill with its fine shrine, Caṇḍikā (Durgā) herself cherished the child like a mother; otherwise, how could he have stayed there so long, content and without anyone to help him?',
        '0.17': 'Sarasvatī, who is made of all sound, ever bows to him of her own accord; yet once the excellent brāhmaṇa set about teaching his son the letters of the alphabet.',
        '0.18': '"Father, this row of letters was written just yesterday — why write it again?" These words of Hari\'s devotee, showing his innate genius, delighted his father.',
        '0.19': '"This child is an ocean of genius; may he not suffer from people\'s envious eyes and tongues" — thinking so, the father taught his son in a secluded place.',
        '0.20': 'Once, prompted by kinsfolk going to a festival and accompanied by his mother, the young lord, whose speech was graced by fine recitation, went to Ghṛtavallī (Neyyampaḷḷi).',
        '0.21': 'There the boy of vast intellect in a child\'s form saw one Śiva, son of Dhautapaṭa, surrounded by a large audience, narrating a sacred story.',
        '0.22': 'Skilled in reasoning, the boy softly spoke these pure words before the people, with a smile: "Narrator, you have explained this differently from the view of the great."',
        '0.23': 'Then, when Vasudeva\'s son had spoken, the people paid no more heed to Śiva: who wants a noisy jackal when a lion cub has begun to roar?',
        '0.24': 'When the people then said, "You tell the story, then," he explained its proper meaning, and was fondled by the wondering men and even by the gods who honour the sprout of victory.',
        '0.25': 'Going home with his mother, he told his father what had happened, asking, "Tell me, father, was the narrator Śiva wrong, or was I?"',
        '0.26': '"Son, what you said was right," he replied, and reflected with wonder: "My child\'s skill is innate — born of the rising grace of my Lord."',
        '0.27': 'Once, when his father, foremost of narrators, was telling a sacred story surrounded by a crowd, the clever boy, a festival for the eyes and minds of all, made him pause and explain.',
        '0.28': 'While various trees were being listed, the one called "likuca" was passed over without its meaning; the boy said softly, "Father, why do you go on without describing what it means?"',
        '0.29': 'When his father did not answer, and the listeners too were eager to know, the boy, on being urged, explained the meaning and won unequalled honour from the assembly.',
        '0.30': 'Seeing him delight the whole world with such charming deeds, and now at the proper age, the excellent brāhmaṇa resolved to perform his upanayana (sacred-thread ceremony).',
        '0.31': 'Fixing a faultless auspicious hour with fitting planetary conjunctions, he, surrounded by loving kin, held a festival crowded with brāhmaṇa families.',
        '0.32': 'The divine ladies — the many Vedas, who longed to dance for ages on the stage of his mouth — rejoiced with their lords at the festival from the sky.',
        '0.33': 'The bright-minded father, kindling the sacred fire with the proper materials and rites, invested his son — adorned, well, his head duly shaved — with the sacred thread.',
        '0.34': '"Serve the fire and your teacher, keep your vows, be of good conduct, and study the true scriptures well" — at this father\'s instruction to the teacher of the three worlds, the gods, present as witnesses, openly laughed.',
        '0.35': 'Seeing his tender son, who surpassed even Kumāra (Skanda) in virtues and was naturally adept in right conduct, the brāhmaṇa took constant delight in teaching him.',
        '0.36': 'Wearing a scrap of cloth like a pauper, and doing such things as walking on foot, unfitting to his glory — ah, this self-concealment of the Lord of the world caused amusement in the assemblies of the gods.',
        '0.37': 'A demon in serpent form, who roamed about tormenting everyone with the ceaseless heat of his venom, once approached him, restless and bent on killing him.',
        '0.38': 'Swiftly raising and spreading his hood, he bit the boy, who remained unhurt; and, his body crushed by the play of the Lord\'s lovely reddish toes, the serpent writhed and lay stretched out.',
        '0.39': 'As if caught in Garuḍa\'s beak, he came under the brāhmaṇa boy\'s foot and died. The gods honoured in their hearts this deed, so fitting for the great.',
        '0.40': 'He whose foot-dust is borne on their heads by the chiefs of the gods — Śiva, Bṛhaspati, Indra and others — in his assumed human form began his studies by bowing at the feet of a brāhmaṇa teacher.',
        '0.41': 'All learning, with all its arts, was ever in his palm like a ball; while he imitated ordinary pupils before his teacher, it shone in his mind together with Viṣṇu, the bearer of the discus.',
        '0.42': 'Between lessons, away from the teacher, he played happily with many clever young students, friends both younger and older than himself.',
        '0.43': 'When a goal was named for a race, he was always first among his swift friends; no wonder he did it effortlessly — he is Vāyu, who outstrips the speed of mind.',
        '0.44': 'In the power of leaping he then outdid not only all people; long before, in Hanumān\'s body, carrying out the Lord\'s command, he had outdone Aṅgada, son of Vālin, and the rest.',
        '0.45': 'At water-play, his face — showered with water by friends whom he beat in the contest, his eyes blinking — wore a smile of special charm.',
        '0.46': 'In play-wrestling he gently threw down strong friends who came at him all together; and when they attacked in earnest all at once, the brāhmaṇa\'s son, laughing, felled them without effort.',
        '0.47': 'Skilled in seizing, pinning, holding fast, lifting heavy weights and the like, he was called "Bhīma" by people who meant it as a figure of speech — yet it was the literal truth.',
        '0.48': '"He just plays, does not recite clearly, and comes home late" — so the brāhmaṇa teacher of the Pūgavana family was not pleased with the teacher of the world.',
        '0.49': 'Once, during a lesson, the angry teacher said to him, who seemed inattentive: "You don\'t study, you rogue! Why is your mind always indifferent, off with your friends?"',
        '0.50': 'When the boy said, "Drilling the lesson quarter-verse by quarter-verse does not appeal to me," the brāhmaṇa replied, "Then, clever talker, recite what comes next as you please."',
        '0.51': 'His flawless recitation of the Veda — the very root of all teaching in phonetics — filled with wonder not only his teacher but the gods as well.',
        '0.52': 'Once, in a lonely wood, he cured his dear friend\'s severe headache — chronic and unbearable — by blowing breath from his mouth into his ear.',
        '0.53': 'It is no wonder that an Upaniṣad heard once was mastered, or that the Bhāgavata became clear to him; by his genius he knew hundreds of Vedic texts he had never heard at all.',
        '0.54': 'Then the Lord, in a lonely place, under the guise of reciting the Aitareya Upaniṣad, expounded the essence of its meaning, and so gave his teacher, as a fitting guru-dakṣiṇā, devotion to Govinda — the seed of liberation.',
        '0.55': '"O master, subdue, subdue the wicked openly and soon; proclaim, proclaim Viṣṇu\'s hidden qualities, delighting your own!" Thus spreading joy among the gods who urged him so, the teacher of the three worlds took leave of his brāhmaṇa teacher.',
        '0.56': 'Thus ends the third canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-04': {
      verses: {
        '0.0': 'Then the wise one — the source of true scripture — reflected with his vast mind, moist with the nectar of compassion for the good, intent on refuting falsehood, and the very dwelling-place of Ramā\'s Lord.',
        '0.1': '"Attachment to Hari\'s qualities comes through detachment from all else, and the standard for people is the conduct of the eminent; so I shall make detachment manifest by taking up the āśrama of the paramahaṃsas."',
        '0.2': '"Moreover, for my Lord\'s cause it would not be fitting for me to be without the \'staff\' (daṇḍa) — the rod of punishment — against those who hate Viṣṇu; and soon Hari\'s sister Durgā will help to break the wicked. So I shall not be a mere bearer of the staff."',
        '0.3': 'Reflecting thus, the meditator on the Infinite, firmly resolved on complete renunciation, then bowed to Hari — who pervades all and gives Himself — to ask His permission.',
        '0.4': 'When asked, "Why do you bow to one who is your own?", he replied, "I have bowed to what is my very own." Then the teacher of the world, instructor of all people, set out in search of a guru.',
        '0.5': 'There lived on earth a certain self-controlled ascetic, whose ornament was great detachment; people plainly called him Acyutaprekṣa ("he who beholds Acyuta") — pure not only in name but in fact.',
        '0.6': 'Earlier, purified in mind by eating excellent food sanctified by the hand of Kṛṣṇā (Draupadī) at a shrine of the Pāṇḍavas, he had lived happily for some years by the bee\'s way of begging alms.',
        '0.7': 'His study of the wrong doctrine, inherited through his lineage, was no sin for the ascetic, because remorse came to him in due course — just as the hunter\'s shot at the lotus foot of Kṛṣṇa, Mura\'s foe, was not held against him.',
        '0.8': 'Knowing his death was near, his guru once spoke these words in private to him — humble, versed in the Upaniṣads, and ever eager to know the truth.',
        '0.9': '"\'I myself am Brahman; nothing exists beyond me, once consciousness shines forth clearly\' — this teaching of the Māyā doctrine has no foundation. Do not trust it, you of good vows."',
        '0.10': '"This identity of the self, enjoined as meditation, has never become direct experience even for my own guru, dear one, nor for the ancients anywhere; so worship Mukunda with joy, to gain true knowledge."',
        '0.11': 'Having given this instruction, the eloquent guru passed to the other world; and the disciple, pondering his guru\'s words again and again, worshipped Indirā\'s Lord who dwells at Rūpyapīṭha.',
        '0.12': 'The Lord, who loves His devotees, served there by that devout seeker of the Supreme, entered a man and told him: "Know me through the excellent disciple who is to come."',
        '0.13': 'To that tranquil ascetic — joyfully awaiting this grace and worshipping the lotus-eyed Lord — came the teacher of the good, who had taken human form for a purpose.',
        '0.14': 'Hearing that their son, detached from the world, had become a follower of the chief of ascetics with his mind set on sannyāsa, the loving parents, worn by separation, came to him at Rūpyapīṭha.',
        '0.15': '"Son, while we two, old and helpless, are still alive, you should not take up the highest āśrama." Speaking these pleading words, they walked round their son and bowed to him.',
        '0.16': 'The Lord said: "Bowing is not proper towards one who wishes to serve you; yet you have plainly bowed to me just now. Ah — so the Creator himself has made you give your permission!"',
        '0.17': 'Finding no reply, the father again pleaded with him, bowed to the chief ascetic and left with his wife; living at home, passing moments that seemed like aeons, he constantly remembered the moon of his son\'s face.',
        '0.18': 'Brooding in grief over his son\'s intention, he once more crossed the great river and came, and found his son, the follower of the lord of ascetics, in a maṭha in a fine village.',
        '0.19': 'The brāhmaṇa, though fearful of offending great souls, was overcome with anger and said: "If my son puts on the loincloth, my vow to do something desperate is firm."',
        '0.20': 'In an instant the Lord tore his own cloth, wore it as a loincloth, and said, "Father, do your desperate deed." Then he added, "But you should not put an obstacle in the way of what is good."',
        '0.21': 'The father said: "Son, the good say there is no merit without caring for one\'s parents; if you turn away, we have no protector, and we two are as good as dead." To him the son replied:',
        '0.22': '"The Śruti declares that the moment a man becomes detached, he may take sannyāsa. Yet, though I am free of attachment, I will not leave you two without first arranging for someone to serve you."',
        '0.23': '"Being learned, I might force myself to bear it; but your mother will not bear separation from you." When the brāhmaṇa said this, the son bowed to him, saying, "Please grant your permission."',
        '0.24': 'Reflecting and finding no answer, the learned father said, "Very well — if your mother agrees." Saying this with difficulty, he went home and told his wife the news.',
        '0.25': 'As Lakṣmaṇa was to Rāma, foe of the night-prowlers, and Arjuna, Indra\'s son, to Bhīma, and Gada to Kṛṣṇa, so a dear and devoted younger brother was born to the all-knowing one, ready to do his work.',
        '0.26': 'Once, visiting home and presenting this brother as the protector of the two, he — with his father\'s consent — spoke to his mother, who was firmly resolved to forbid his sannyāsa.',
        '0.27': '"Mother, if you ever wish to see me again, consent to my taking the highest āśrama; otherwise I shall leave this land and never again come within your sight."',
        '0.28': 'When her son spoke so, the good mother, thinking that never to see him again would be like his death, was deeply shaken, and with great difficulty refrained from opposing his wish.',
        '0.29': 'Then the teacher of the world approached his guru and won his favour — he who enjoys the favour of the best of gods. That lord of the gods, who always belongs to every āśrama, now formally took up the highest āśrama.',
        '0.30': 'Knowing the right time, he performed the entire sequence of rites strictly by the prescribed method, and, for the pleasure of Hari who is ever pleased, solemnly declared his complete renunciation again and again.',
        '0.31': 'The wise describe the praṇava (Om) as beginning with three measures and ending in endless measures; this ascetic, who bears the form of the future four-faced Brahmā, was then marked out as the one truly entitled to its japa.',
        '0.32': '"Pūrṇabodha (Pūrṇaprajña) — one whose knowledge is full and lofty, as befits his virtues": that was the name the illustrious guru, honoured by brāhmaṇas, gave him; and the name was no mere sound — he himself was the one who would expound the mantras.',
        '0.33': 'With no unguents and no colour on his face, his very ornament became an ornament to the world; seeing him holding the palāśa staff, all beings felt that his natural beauty was beyond compare.',
        '0.34': 'Though Śeṣa, Rudra, Garuḍa and others, awaiting their turn, bowed to him, he bowed to the ascetics beginning with his guru — ah, how grand is the play-acting of the great!',
        '0.35': 'Watching the conduct of one who meant to teach the special discipline of the highest āśrama, the chief ascetic, steady of mind, himself received special instruction and was inwardly amazed.',
        '0.36': 'When the great-minded one joyfully bowed to the Lord who dwells at Raupyapīṭha, the Lord who reclines on the serpent, entering a man, at once took him by the arm.',
        '0.37': '"As the fruit of your long service to me in your desire to know the truth, I give you this one" — saying so, the Lord led him forward and gave him to Acyutaprekṣa.',
        '0.38': 'Receiving that grace with reverence and joyfully recalling his own fulfilment, the guru, though free of attachment, became attached to him — for the ornament of the unattached is attachment to the good.',
        '0.39': 'When the great-hearted one, wishing to go to the heavenly river Gaṅgā, bowed again and again seeking permission, the guru, distressed and fearing the fire of the coming separation, turned in prayer to his Lord.',
        '0.40': 'Then Hari, the ocean of compassion, entering someone, said to him: "On the third day from now the heavenly river will come to our own tank for your sake; so do not go."',
        '0.41': 'In the Gaṅgā water that came there by His command, people bathed together with Pūrṇabuddhi; and ever after, once every twelve years, she comes there, bearing the mark of His grace.',
        '0.42': 'When ten days had passed since he took the highest āśrama, he put up a written challenge and defeated famed debaters harsh with much logic, Vāsudeva Paṇḍita and others.',
        '0.43': 'At the urging of his guru, who wished to make his disciple adept, the great soul began here to hear the Iṣṭasiddhi — an ocean of quibbles and specious rejoinders — though he had no regard for it.',
        '0.44': 'When he pointed out a set of thirty-two faults in its very first verse, and the guru said, "That is answered later on," he said to him, "Then let it be stated."',
        '0.45': 'When the chief ascetic said angrily, "I am not able to expound it to you," a seed of doubt about its soundness sprouted even in men skilled in the Māyā doctrine.',
        '0.46': '"The learned should teach, and the unlearned who seek liberation should surely listen — an ascetic above all" — urged by people with these words, Pūrṇadhī began to expound the Māyā doctrine.',
        '0.47': 'Learned, clever and ambitious men came eagerly to hear his exposition — unbroken in presentation, free of doubt, faithful to tradition, and firm in its answers.',
        '0.48': 'Once, when five or six brāhmaṇas who were hearing the Bhāgavata near the guru read a passage that was found written in many variant forms, the Lord firmly declared one reading.',
        '0.49': 'When they asked, "Other readings are possible too; how do you decide on this one?", the great-hearted one, through his knowledge of Mukunda, clearly stated the one reading composed by the Lord (Vyāsa).',
        '0.50': 'The best of ascetics said, "If you know the true state of the world-teacher\'s work, recite here the prose passage in the fifth book"; and the great-hearted one recited it exactly in the way he had said.',
        '0.51': 'At the guru\'s bidding all the disciples then examined every manuscript to test it; a whole set of chapters found in only one of them, he had left out of his recitation.',
        '0.52': 'When the guru asked, "Victorious one, how does what you never studied in this life shine so clearly in you?", the one of measureless intellect replied, "In former lives I knew all this long ago."',
        '0.53': 'Thus, from the many workings of his mind that astonished all, his fame, though new, spread far through the world — like sunlight that destroys the spreading darkness, like moonlight that delights the lilies that are good people.',
        '0.54': 'Thus ends the fourth canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-05': {
      verses: {
        '0.0': 'Chosen by his guru for the weighty charge of ruling his own kingdom, the learning of Vedānta, the large-hearted one was then anointed with waters filled with lotuses.',
        '0.1': 'Because he was a vessel of the Supreme, whose form is bliss, and was to compose true scriptures that bestow bliss, the name "Ānandatīrtha" given by his guru was a perfectly fitting description of him.',
        '0.2': 'Once an ascetic, a friend of Acyutaprekṣa, came there surrounded by many disciples; his arrogant disciples, trained in the art of inference, sought to defeat the great-minded Madhva.',
        '0.3': 'They promptly advanced an inference, fearsome to opponents, that difference cannot be established; the one of unbroken intellect, skilled in handling a thesis, plainly demolished it — as the king of birds tears apart a serpent.',
        '0.4': 'Next they argued, "The world under dispute is unreal, because it is an object of cognition, like things beyond dispute (such as shell-silver)." He countered with the inference, "The world under dispute is real, because it is cognized as real, like a pot and the like."',
        '0.5': 'When they eagerly charged his reason with over-extension, he, unperturbed, at once replied, "Shell-silver and the like are not cognized as real — what is cognized otherwise is a different matter," and with such answers defeated them.',
        '0.6': 'Showing that in the disputed case inferences can be framed for both reality and unreality, and himself demonstrating that inference alone is not conclusive there, he defeated all the learned in assemblies and came to be called "Anumāna-tīrtha" as well.',
        '0.7': 'Then there arrived Buddhisāgara, foremost among the opponents of the Veda, together with Vādisiṃha — roaming the earth in search of rivals, breaker of the elephants that were the leading debaters.',
        '0.8': 'Wishing to conquer this man so proud of his great fortress, the guru, whose mind dwelt on Mukunda, swiftly drew — through a disciple\'s hand, from the quiver that was the maṭha — his sharp, well-feathered arrow: Sukhatīrtha (Ānandatīrtha).',
        '0.9': 'Learning that a crowd of people, eager and curious about the contest, had hurried there, the one of weightiest mind came and bowed to his guru, who was staying at the great temple of Rūpyapīṭha.',
        '0.10': 'In the midst of the circle of scholars he refuted again and again the weighty words of Vādisiṃha with sharp, measured, swift words — as a skilled archer splits a hurled mace with arrows.',
        '0.11': 'Then the other, Buddhisāgara, jealous, loudly put forward a certain point in eighteen different ways; and for a while the people grew doubtful of victory for Pūrṇaprajña, conqueror of the world.',
        '0.12': 'Then the vast-minded one, swiftly cutting down the myriad alternatives, shone all the more with a smiling face — like the sun dwelling in the sky (Viṣṇupada), destroying masses of darkness with its pure rays.',
        '0.13': 'Like Agastya, the pitcher-born, who drank the ocean, the great-minded one easily made light of this "Ocean of Intellect" (Buddhisāgara) — unfathomable in its own eyes, overflowing its bounds, arrogant, having swallowed all other streams of learning.',
        '0.14': 'The two rogue debaters said, "Let the debate continue tomorrow"; Madhva replied, "If an answer occurs to you, say it today." People judged them beaten, and were certain of it when the pair fled in the night.',
        '0.15': '"Ah! The glory of victory that the Ocean of Intellect and that best of debaters had amassed over long years of touring the earth, this one has won in a moment without any effort!" — so the people marvelled.',
        '0.16': 'Once, while expounding the commentary composed by Maṇimān (as the poem calls him), surrounded by men skilled in logic, Ānandatīrtha, laughing in jest, spoke words that delighted the gods.',
        '0.17': '"When the true sense of the sūtras and the intent of the commentary are examined separately by those of pure understanding, setting aside fierce hidden bias — ah, no worthy agreement between the two is to be seen."',
        '0.18': 'As he said this and pointed out serious faults in that commentary again and again, even those listeners, astonished though they were, could not with all their effort firmly answer them.',
        '0.19': 'These eloquent men said: "Then state the other meaning of this sūtra, since you merely refute the commentary — a meaning that poets like yourself could not fault in any way."',
        '0.20': 'He then loudly set forth a possible meaning of the sūtra, with natural word-order, supported by the Vedas and by smṛtis shown to be authoritative — the stage-manager, as it were, for the dance of the commentary that was soon to come.',
        '0.21': 'Whether they were free of envy and came wishing to learn, or envious and came wishing to win — learned in scripture and great logicians — again and again he brought them to defeat by this method.',
        '0.22': 'Once the noble Madhyageha, gentle of mind, came to him and was gladdened; even when saddened for some reason, a good man who longs for an ocean of virtues is soon pleased again.',
        '0.23': 'The learned father drank with the cupped hands of his eyes the imperishable nectar of radiance held in the vessel of his son\'s body, and with the cups of his ears the nectar of learning that filled the great pitcher of his words.',
        '0.24': 'During a friendly debate between guru and disciple, when such an occasion arose, the guru said to him, half in challenge: "If you know the meaning of the sūtras, then write a commentary at once."',
        '0.25': 'That supreme king of swans took only the instruction in it, as a swan takes pure milk, and ignored the useless taunt mixed with it, like water; for the good take delight in the portion of virtue.',
        '0.26': 'Once the senior ascetic born of the Likuca family — endowed with detachment, boldness, eloquence and the other ornaments of the paramahaṃsa life — spoke to him with deep devotion:',
        '0.27': '"If these commentaries and the like run counter to the treasures of Vedānta\'s settled conclusions, what of it? Tell us, as befits the discerning, the sense truly intended by the sūtras and the Upaniṣads."',
        '0.28': 'At his words, as at the coming of autumn, all the quarters shone full of good; and the moonlight from the moon-face of Ānandatīrtha — his commentary, illuminating Viṣṇu\'s nature as moonlight lights the sky — shone forth.',
        '0.29': 'Once, setting out to conquer the southern quarter guarded by Yama, together with Acyutaprekṣa, the all-wise one bowed at Viṣṇumaṅgala to Viṣṇu, the auspiciousness of the world, who adorns that place.',
        '0.30': 'There, when the host who gave alms, to test him, kept serving heaps of plantains and he ate them all with no effort, his guru, unable to contain his wonder, said to that best of noble men in private:',
        '0.31': '"At the end of the meal your slender belly was filled with more than two hundred plantains, yet it shows no heaviness at all. How can that be? Good soul, tell me truly."',
        '0.32': 'Then he, whose mind is on the Lord of the universe, said: "Know that in my belly dwells a blazing fire the size of a thumb, ever beneficial and able to consume everything."',
        '0.33': 'Passing through lands with many turbulent rivers, and past doctrines armed with logic and many meanings, the fine-minded one went on by the road he had chosen.',
        '0.34': 'On the way, seeing the Payasvinī river — worshipped by brāhmaṇas, granting purity of mind, an ornament of Kerala, which playfully topples whole rows of trees — he thought of the goddess Caṇḍikā, who was to manifest there.',
        '0.35': 'Then, journeying on step by step, he arrived at the holy city of Anantapura (Anantaśayana) and bowed to Śrī\'s Lord, the lotus-navelled one who reclines on the serpent, beautiful as the blue lotus.',
        '0.36': 'The supreme knower of final truths expounded the Vedānta-sūtras to his disciples in the assembly, establishing again and again that Brahman, called Acyuta, the ocean of qualities, is distinct from the host of souls.',
        '0.37': 'Then a "confounder" (saṅkara), born at a place called Aprāṃśu-nūtna and bent on enmity, said there jealously: "It is a grave transgression for those who have written no commentary to pronounce on the meaning of the sūtras."',
        '0.38': '"Give your answer, if one occurs to you. We shall write a commentary here — for composing is not barred to those who bear the staff, the teachers of the world." All the people applauded these smiling words of the guru.',
        '0.39': 'When the wise declared that the Lord\'s body bore all the marks of a great person, others, by way of disparagement, spoke only of the excessive heaviness of his hips.',
        '0.40': 'When the critic set forth at length before the full assembly the supposed faults of such hips from the science of bodily marks, and was answered, he, unable to bear it, vowed to break Madhva\'s staff — such is the nature of the wicked.',
        '0.41': 'Having bathed at the sacred fords there, he soon bathed at Kanyā-tīrtha (Kanyākumārī), that excellent ford; and, plunging into the ocean at the Setu, Sukhatīrtha bowed to Viṣṇu as Śrī Rāma, the Lord of that place.',
        '0.42': 'When that demonic man in ascetic\'s garb approached, Madhva held up his staff and said laughing: "If you cannot break this staff, fierce one, you are impotent, unlearned, and your words are barren."',
        '0.43': 'Bowed with shame and pursuing his own interest, the wicked man was then ignored by the leading brāhmaṇas, while the debaters said: "Who here could hate the wise one who delights the world with his moon-face?"',
        '0.44': 'Whatever branches of learning were brought up in assemblies by the many learned men who met him, in each and every one the radiant lord of learning shone forth and defeated them.',
        '0.45': 'Unshaken by the antics of the wicked, who were feeble here, the great-minded teacher stayed there four months (for the rainy-season retreat) — like a lion that has gone into its cave, unconcerned by dogs.',
        '0.46': 'The keen-minded one came to Śrīraṅgam and bowed to the Lord reclining on the serpent there — an ocean of beauty, who brings blessing to the good, fanned by the cool breezes of the Kāverī.',
        '0.47': 'Then, turning back, bowing to the Supreme Person in many temples as he journeyed, and revealing his superhuman excellences, he gradually made his way toward the north.',
        '0.48': 'Gazed at everywhere by people with wondering eyes, he of most auspicious form reached some fine villages on the bank of the Payasvinī and entered a certain temple.',
        '0.49': 'Excellent brāhmaṇas, who had duly studied the Veda with its six limbs and could settle the explanation of its meaning, came eager to learn to that extraordinary person, renowned for carrying the world across.',
        '0.50': 'People crowded in, eager to see him — his smile like the moon, his eyes like lotuses, golden-hued, gracious in speech, wearing no ornaments yet himself the ornament of the world.',
        '0.51': 'A sun eclipsing the bright stars of learning, a lordly lion splitting the brows of the elephants that were false debaters with their sophistry, a moon gladdening the night-lilies of eager people\'s eyes, his form the jewel of every assembly — so shone Ānandatīrtha.',
        '0.52': 'Thus ends the fifth canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-06': {
      verses: {
        '0.0': 'Then in an assembly there, a senior scholar, pointing to a certain hymn of the Aitareya, said: "The assembly wishes to hear from your reverence the sense of this hymn."',
        '0.1': 'He recited it with weighty perfection of syllables, unhurried, in even measures, every mark exact, deep and heart-pleasing like the rumble of a rain cloud — and then explained its meaning.',
        '0.2': 'In their minds they granted that by the correctness of this recitation he surpassed even Bṛhaspati, teacher of the gods; yet aloud they said the hymn had a different meaning.',
        '0.3': 'He replied: "That may be so; this meaning too is possible. Know that the Vedas bear three senses; the Mahābhārata ten; and the thousand names of Viṣṇu even a hundred."',
        '0.4': 'When the broad-minded one said this, the brāhmaṇas there, eager to defeat him, said with mocking smiles: "Then describe a hundred meanings of one of Hari\'s names."',
        '0.5': '"I shall describe it all to you; you must repeat it accurately," he said; and saying "Certainly," they made a very determined effort.',
        '0.6': 'Showing the ways of joining stem and suffix laid down in grammar, the pure-minded one at once set forth the meanings of the name "Viśva," each established by hundreds of Upaniṣadic texts.',
        '0.7': 'By the time he, undaunted and speaking without a pause, had completed the hundred meanings, they — too weak to retain what was described — were utterly bewildered.',
        '0.8': 'Though many were experts in the Veda and its limbs, trained in the epics and very bold, they could not grasp what he said — as a cluster of wells could not hold the waters of the cosmic flood.',
        '0.9': '"Your genius is rare even among the gods — what then of fickle men? Forgive us, gentle one, knower of all; salutations to you!" So saying, they bowed to him.',
        '0.10': 'Then the wide-minded one, joined by all those born in the fair land of Kerala — skilled in Veda and śāstra and eager for the wealth of learning — went on to another temple.',
        '0.11': '"Alas, this man keeps stripping of their pride even men skilled in logic; how should he not humble the pride of us, natives of this land, gathered here?"',
        '0.12': 'Conferring thus, those excellent brāhmaṇas, led by men from other lands, approached and asked him the meaning of a hymn that praises the giver and censures the miser.',
        '0.13': 'Making it clear, he said that the word "pṛṇīyāt" comes from the root pṛṇ ("to fill, to give"). Then to the brāhmaṇa who wanted victory and claimed it was the root prī ("to please"), he said:',
        '0.14': '"You cannot even tell apart the prefixes like pra; go, fool, and practise writing your letters in the dust!" So scolding him, the one of lovely laughter laughed, leaving the envious dumbfounded.',
        '0.15': 'Through that incident they recognized the broad-hearted one\'s mastery of every science, and bowed with great respect to him to whom the hosts of heaven bow.',
        '0.16': 'In another assembly, explaining the heart of the fine hymn that tells how a maiden, honoured by Indra, received bodily beauty from him, he described the word "Apālā" as meaning "a very young girl."',
        '0.17': 'When a scholar there insisted that the word means "a woman afflicted with white leprosy," he said, "A wise man will come here before long; ask him," and went on his way.',
        '0.18': 'Soon a learned man of just such appearance came to that region and, remarkably, explained the sense of that word to them exactly as the crest-jewel of scholars had said.',
        '0.19': 'These broad-minded men came to believe not only that he commanded all Vedic learning and that his every word rested on authority, but also that he knew the past and the future.',
        '0.20': 'Whatever subject was raised on the spot, he knew it fully; so in every assembly of the learned he became renowned as "the all-knowing ascetic."',
        '0.21': 'As the full moon floods the sky with moonlight, so Pūrṇaprajña, friend of the lilies that are good people, filled with his far-spreading fame even every land he had not visited.',
        '0.22': 'Paying homage to Indirā\'s beloved in many beautiful temples along the way, the thoughtful one soon reached Mukunda, Lord of Raupyapīṭha (Uḍupi).',
        '0.23': 'There he saw the Veda as a noble lady (like Draupadī): her form shining with the rich wisdom of the best brāhmaṇas, lovely of limb, adorned with a jewel-garland bright with sūtras (also: threads), the very ornament of the worlds —',
        '0.24': '— radiant with lovely quarter-verses, words and recitation-orders (also: feet and steps), rich in clear syllables and qualities (also: complexion), clothed in a garment that suits the bearers of the great Bhārata (the epic that interprets her), and lovely in her accents (also: voice) —',
        '0.25': '— engaged in the Rājasūya and other great sacrifices, her heart fixed on Vāsudeva\'s qualities, skilled in teaching every dharma, revered by people like a mother —',
        '0.26': '— in anguish at being dragged by her crowning locks (the Upaniṣads) in the assembly by a wicked man of deceit (māyā), who abandoned the great path of justice (and of logic) and even sought to establish his own lordship —',
        '0.27': '— whose agony at being dragged was ignored even by a few good men, wretched and driven from the right path by the force of Kali (also: of the dice), and which some looked upon with deep grief —',
        '0.28': '— crying aloud again and again, "Vāsudeva! Bearer of the earth! Lord!", bearing in her heart the Unborn, free of all fault, full in the six excellences, distinct from all —',
        '0.29': '— crying, "Let the wise stop this! Alas, alas, this is not dharma!" — most cherished by Kṛṣṇa, faultless, with no other refuge, longing for protection.',
        '0.30': 'Seeing the whole body of the Veda in this plight himself — as Bhīma, foremost of the Bharatas, once saw Draupadī, born of the altar — the ocean of compassion, firm of mind, made an unshakable vow to subdue the wicked side.',
        '0.31': 'Wishing to spread far that foremost treasure which never diminishes however much it is enjoyed, he composed the commentary on Hari\'s Gītā (the Gītā-bhāṣya) and presented it to his venerable guru.',
        '0.32': 'When the broad-minded master of reasoning asked leave to go on pilgrimage, Puruṣottamatīrtha (Acyutaprekṣa) granted it, trusting to the protection of Puruṣottama.',
        '0.33': 'Like the fragrant breeze of the Malaya hills — free of dust (also: of passion), praised on earth, ever followed by bees (also: by disciples), easing the heat of good travellers — the portion of Vāyu set out for the north.',
        '0.34': 'The one of keen intellect, simply by immersing himself in them, thoroughly purified both kinds of tīrtha on earth — the sacred waters and the holy teachers, rich in purifying words (also: rays).',
        '0.35': 'Ever clinging to Vāsudeva\'s feet, surpassing even Śiva in radiance, famed for destroying sin — in all this he far excelled the stream of the Gaṅgā (which flows from Viṣṇu\'s foot but rests below Śiva\'s head).',
        '0.36': 'Here and there, as he journeyed, he performed deeds that amazed the three worlds and bring happiness by mere remembrance, and reached the region of Badarikāśrama that is within human reach.',
        '0.37': 'Bowing to the Supreme Lord known here as Nārāyaṇa, who adorns the whole of Bhārata, the one of abundant wisdom offered Him the Gītā-bhāṣya as a gift.',
        '0.38': 'For His pleasure, sending the people away, he read the excellent commentary before Him; and in it Pūrṇaprajña said, "I explain the sense of Urukrama\'s (Kṛṣṇa\'s) Gītā according to my ability."',
        '0.39': 'The Father of the world said: "You are fully able to tell all its meaning, even the subtlest; since you have not told it all, the word here should be \'in part\' (leśataḥ), not \'according to my ability.\'"',
        '0.40': 'When the Lord gave this pronouncement, even the disciples who lay asleep heard it: "Let it be said so!" — the word Hari spoke again and again, striking the ground.',
        '0.41': 'Noting that change of word made by the Supreme, whose body was seated there as the sacred image, the one of great intellect, who knew His intent, rose and explained it to the disciples.',
        '0.42': 'Every day at dawn he bathed in the icy water of the Gaṅgā, which men afraid of the snow will not touch — for he is a portion of Vāyu, lord of the deer-drawn winds.',
        '0.43': 'He kept strict silence and a complete fast — though already pure in heart — seeking the special pleasure of Hari who is ever pleased, and meditated on the Lord in the Ananta-maṭha.',
        '0.44': 'There, after a full cycle of days (a maṇḍala), Mukunda — whose arrival others could tell only by the blaze of light they saw — summoned Madhva, whose mind delighted in His feet, to His own hermitage.',
        '0.45': 'The Lord had come by night; when the thousand-rayed sun rose, the noble-hearted one, still keeping silence, compassionate and intent on instructing his disciples, wrote these words:',
        '0.46': '"No place destroys sin as this one does; no water equals the water of this tīrtha; there is no god like Viṣṇu; and nothing is as beneficial as our teaching."',
        '0.47': '"This person now goes, longing to behold the unconquered Lord in the form of Vyāsa. Whether he returns here or not, He knows. Farewell to you." So writing, Madhva departed.',
        '0.48': '"Lord, Lord, alas, do not leave us here without a master; you are so compassionate!" — the disciples thought this, but did not say it, fearing to cross their master\'s wish.',
        '0.49': 'Unable to bear separation from his true guru, the ascetic Satyatīrtha followed him — he who had three times heard from Pūrṇaprajña the deepest meaning of the Aitareya texts.',
        '0.50': 'Though he ran after him along the difficult path, he could not catch up as the sun reddened, for the master strode playfully and swiftly over rocks far apart across the chasms.',
        '0.51': 'Urged on from afar by the guru with a gesture of his hand, without even turning round, the frightened disciple crossed in a moment the whole way the guru had covered that day.',
        '0.52': 'Meeting his own people at the hermitage there, he told them of the master\'s gracious power and of that wondrous leap, and ever after remembered it with them.',
        '0.53': 'Swift as the wind like Hanumān, king of monkeys, terrible to demons like Bhīmasena, he whose very name destroys sin shone forth as he climbed the peaks of the king of mountains.',
        '0.54': 'Going on, fearless and wide-eyed, he beheld the great snowy mountain, teeming with creatures and birds, rugged and vast with snow (the verse is an elaborate play of repeated syllables).',
        '0.55': 'The mountain seemed like the Lord himself: its smiling lotus-lakes like Kamalā embracing Him, its vast expanse a couch like Ananta\'s coils for the joy of good people, lofty, crowned with clusters of blossoms, and gleaming with emerald-like slopes —',
        '0.56': '— with hosts of great sages bowing at its foot, its sky shining like a golden garment, its clusters of gems and golden slopes like splendid ornaments and bracelets, lovely with its garland of forests: seeing that "bearer of the earth," Ānandatīrtha was reminded of Mura\'s foe, whose very form is bliss.',
        '0.57': 'Thus ends the sixth canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-07': {
      verses: {
        '0.0': 'Then, on another slope of the Himālaya, the all-knowing one beheld the famed supreme hermitage, abode of Śrī, adorned with a special grove of badarī trees.',
        '0.1': 'There both shone alike — the wondrous trees and the brāhmaṇas: enduring snow, rain and the sun\'s glare, famed for their wide shelter (also: great sacrifices), giving refuge to birds (also: to the twice-born), and reaching the sky (also: touching Viṣṇu\'s feet).',
        '0.2': 'It was alive with fine birds led by parrots, whose songs were nectar to the ear (also: with sages like Śuka), and with supreme swans of spotless white, their hearts steady, dearest to Kamalā (also: paramahaṃsa ascetics dear to Lakṣmī).',
        '0.3': 'Filled with masses of flowers (also: of good-minded souls), granting the heart\'s desire, hard for the small to reach, whose creatures bore no enmity to one another — it was truly like Vaikuṇṭha, the home of Acyuta.',
        '0.4': 'Seeing him enter the hermitage, bearing the thirty-two noble marks, the sages, who knew the essence of qualities, wondered thus:',
        '0.5': '"Who is this extraordinary person approaching — like a matchless golden palm tree, lotus-eyed, his face like the spotless moon, with the gait of a royal elephant and mighty arms?"',
        '0.6': '"The moon is gentle but not radiant enough, the sun radiant but wholly fierce; so no likeness can be found in the worlds for this ocean of virtues."',
        '0.7': '"This steady-minded one, unwearied, bears the signs of the paramahaṃsa ascetics; though in human form, he fills us with great wonder."',
        '0.8': '"Surely this is the wise four-faced Brahmā himself, or Vāyu, coming in an ascetic\'s form, longing to see the Lord of the Vedas; otherwise he could not bear the foremost marks of all."',
        '0.9': 'While the curious sages, having observed his marks, pondered thus, he, walking on without delay, saw close by a tree, the finest of the trees of heaven —',
        '0.10': '— smooth-barked, lofty and spreading, its many branches like hoods and its flowers like jewels: like the Lord Ananta (Śeṣa) himself, standing close by to serve the Lord.',
        '0.11': 'With leaves of wondrous variety and many hues (also: plumage), shielding from the sun\'s rays (also: warding off serpents), delighting the sages, and dear above all to Indirā\'s Lord — it was like Garuḍa, king of birds.',
        '0.12': 'Granting the great fruit that is immortality, hard to win for those without devotion to Hari, sheltering the good Purāṇas and the Bhārata (also: old birds), with its many branches it was like the Veda in bodily form.',
        '0.13': 'Then on its platform — very broad, spotless and lovely — the one of infinite intellect saw the most excellent ascetics, like gods in heaven.',
        '0.14': '— some shining in groups of seven, countless, rich in virtue yet beyond the three guṇas, free of anger, pride and the rest, without enjoyments, living ever on air alone.',
        '0.15': 'There, in the midst of the circle of sages, the ornament of the whole sphere of the three worlds, Pūrṇaprajña beheld Hari as the son of Satyavatī — Vyāsa.',
        '0.16': 'Though he always saw Him clearly in the spotless lotus of his own heart, seeing Him now again and again, ever new, he thought in wonder:',
        '0.17': '"This is surely Nārāyaṇa alone, the spotless ocean of countless qualities, whom, as ordained, Satyavatī bore here to Parāśara."',
        '0.18': '"From the milk-white ocean of His mind, churned by the great mountain of compassion for the good, there arose — like Lakṣmī, beloved of the demons\' foe — the lovely triple Veda."',
        '0.19': '"From this same ocean came the Purāṇas like the white wish-granting cow and the Mahābhārata like the Pārijāta tree; and then was born of itself the supreme nectar — the Brahma-sūtras."',
        '0.20': '"Bestowing unhindered, abundant grace on good people such as the sons of Pāṇḍu, this one of lovely speech long walked the earth to protect true knowledge."',
        '0.21': '"Now, to let the age of Kali run its course — as the sun withdraws to let the night follow — the Lord dwells in this hermitage and has ceased to be visible to people\'s eyes."',
        '0.22': '"And here is His body to be seen — lovely in lustre as an opened blue lotus, seated on the supreme deerskin seat of yoga — delighting my heart and eyes."',
        '0.23': '"It is filled with countless qualities — His own complete, innumerable virtues; it is free of every defect; it is made purely of being, consciousness and bliss."',
        '0.24': '"The dust of His lotus feet is borne on the head by Kamalā (Lakṣmī), lotus-born Brahmā and Vāyu, and by Garuḍa, Śeṣa, Śiva, Indra and the rest — and ah, I too bear it again and again!"',
        '0.25': '"I bow to the Lord\'s two feet, marked with banner, thunderbolt, goad and lotus — red by nature, yet as if reddened by pressing upon the love in devotees\' hearts."',
        '0.26': '"His toenails, which rest on Viṣṇu\'s foot alone (as the sun rests in the sky, Viṣṇu\'s step), by their own radiance destroy both darknesses, outer and inner, and so outshine the new-risen sun."',
        '0.27': '"For His feet, with their tender soles and toes and hidden ankles, the best of poets can find no comparison — except each other."',
        '0.28': '"His pair of shanks — of fitting weight (also: worth), tapering gradually, pure, radiant, well-rounded (also: of good conduct) — grant those who worship them here a form like His own."',
        '0.29': '"The yoga-band that binds His unmoving seat, a fine girdle that grants every wish once gained, embraces Hari all around without ceasing — surely it is most blessed, I think."',
        '0.30': '"He shines most wondrously with the lovely, excellent deerskin, beautiful with a splendid sheen, clinging to his broad and noble hips."',
        '0.31': '"In this belly — slender, graced with a deep, lovely navel and gentle folds, soft and beautiful — the lotus-navelled Lord holds the whole sphere of the cosmic egg."',
        '0.32': '"On His broad chest, from which the welfare of the good springs, the crest-jewel of the sage-lineage wears two things: the pure triple sacred thread, made of the three Vedas, and the supreme Brahma-sūtra (both meanings of the word)."',
        '0.33': '"To his own Father, the Lord — unequalled and unsurpassed — Brahmā offered this ornament that clings to His neck, radiant as a mass of suns, a banner of victory over the three worlds."',
        '0.34': '"For His two lotus-hands, tender and red, shining with the marks of the discus and the lotus, and for His broad, full, rounded arms, we find no comparison at all."',
        '0.35': '"One hand of the Lord, held in the noble gesture of teaching, cuts away the ignorance of His worshippers; the other, resting on His knee, is supremely auspicious, having broken every great fear."',
        '0.36': '"The Teacher\'s neck, marked as if by the three Vedas ever flowing from it of their own accord, is seen with three fine lines, rivalling a conch."',
        '0.37': '"This face of the crest-jewel of the gods, by its own beauty, eclipses the charm of a host of moons from which every stain and shadow has vanished."',
        '0.38': '"When He smiles, the row of His white teeth, set in the glow of His red lips — supreme beauty — would shame a fresh string of pearls gleaming between leaves of ruby."',
        '0.39': '"Ah, this speech of the Lord of the Vedas answers in a single word a thousand excellent questions put by gatherings of brāhmaṇas out of curiosity!"',
        '0.40': '"The glance of the long lotus-eyed one, with a smile that delights the world, comes to me, caresses me, embraces me and makes me whole."',
        '0.41': '"The tulasī shining near His ear, lovingly placed there, seems to whisper: \'Let not the lotus and other flowers jealously steal my place beside my Lord.\'"',
        '0.42': '"The creation, destruction, birth and all else of the worlds — even of Śiva and lotus-born Brahmā — come from the slightest play of these brows of the Lord of the worlds."',
        '0.43': '"The mark on the brow of Him who is the ornament of the three worlds has gained surpassing beauty, like a row of bright red stones on the summit of a sapphire mountain."',
        '0.44': '"Seeing the world-teacher\'s body adorned with its circle of matted locks — like a fresh rain cloud ringed with fine lightning — I have reached fulfilment."',
        '0.45': '"Not even Ramā, counting without ceasing, can count the endless good qualities that shine in the dust of His toenails; who else could tell His supreme qualities?"',
        '0.46': '"I, who have looked on the cosmic egg with its nine coverings as merely a house and felt no wonder, am now — no wonder — filled with wonder at the sight of this form of my true guru."',
        '0.47': 'As the great-minded one reflected thus and passed beyond the outer path, he reached with his body too the king of the Vedas, whom his mind and eyes had already reached.',
        '0.48': 'His form bowed under the weight of devotion to his guru, he at once joined his palms, half-closed his eyes for a moment, and simply worshipped his guru.',
        '0.49': 'Adorned with the ornament of humility, performing clearly the eight-limbed prostration, that blessed and fortunate one bowed at the lotus feet of the most worshipful Lord.',
        '0.50': 'Seeing that dearest one, rich in every virtue, bowed before him, the son of Parāśara quickly reached out and raised him up with his two lovely hands.',
        '0.51': 'The Lord of the Vedas, his heart brimming with the nectar of love, his face smiling and eyes wide with joy, quickly drew close and embraced the one of measureless intellect.',
        '0.52': 'If a mighty dark cloud risen from the Yamunā, Yama\'s sister, were to merge with a stream of the golden Jāmbū river, then the dark-hued Vyāsa embracing golden Madhva might be compared to it.',
        '0.53': 'If these two Haris, born in excellent brāhmaṇa lines, wore royal ornaments, they would be the exact image of their own former selves born in royal clans — Kṛṣṇa and Bhīma — embracing each other.',
        '0.54': '"Even Śuka never received from his father — the father of the world\'s father — such complete fondness as this blessed one has received!" So the ascetics marvelled greatly.',
        '0.55': 'His disciples, cultured and knowing their guru\'s wish, humbly offered him a fitting seat — as Mukunda\'s servants would offer one to four-faced Brahmā.',
        '0.56': 'When the truthful son of Satyavatī said "Be seated" and sat down himself, Madhva, honouring the great sages there with gentle smiles and glances, took his seat.',
        '0.57': 'The hosts of sages, versed in proper conduct, recognizing him as most eminent, honoured him duly; and hearing the conversation of these two masters of poets, so sweet to the ear, they were filled with supreme joy.',
        '0.58': 'Come down to earth for the sake of the good, as embodiments of bliss and knowledge, the two gods Viṣṇu and Vāyu — named Vedavyāsa and Ānandatīrtha — shone resplendent there in that hermitage.',
        '0.59': 'Thus ends the seventh canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
    'sumadhva-vijaya-08': {
      verses: {
        '0.0': 'Leading the minds of the ascetics to great wonder by his own excellences, foremost among them the brilliance of his genius, the one of vast intellect once quietly approached the Lord of the Vedas in a lonely spot in the forest.',
        '0.1': 'The gods judged that approach fitting: discipleship suits one who understands all that is taught even better than Śeṣa, and being his guru suits the Lord of the good, teacher of the great-minded.',
        '0.2': 'Kṛṣṇa (Dvaipāyana) filled once more with the highest truths a mind that was already full; and Madhva took in the Lord\'s mind, vast as a city, which had long been his own dwelling — a wonder!',
        '0.3': 'The one of boundless heart soon heard from the Infinite One the highest meaning of the countless scriptures, together with its true sense in the epics, the lovely Purāṇas, the sūtras and the beloved Pañcarātra.',
        '0.4': 'Though this foremost of the "upright" souls (ṛju) already knew it all of himself through endless births, the Lord who reclines on the serpent, by the power of His great grace, refined his understanding still further.',
        '0.5': 'Then, enriched by the company of Bādarāyaṇa (Vyāsa), the one of measureless mind went on to pay homage to Hari\'s other form, called Nārāyaṇa, shining in another hermitage.',
        '0.6': 'In that best of hermitages the man of abundant wisdom saw the Primeval Person, like a blazing fire without smoke, wearing fine bark garments and a girdle of muñja grass, with a shining coil of matted locks.',
        '0.7': 'He seemed to dwell ever in the forest in austerity — the conquest of the unconquerable senses — yet He ceaselessly delights in the abundant, pure, self-sufficient bliss that is His own nature.',
        '0.8': 'Gazing in wonder, with eyes wide as blossoming lotuses, at that son of Dharma, so hard for the unrighteous to reach, the one of vast mind reflected thus within:',
        '0.9': '"This is surely the Supreme, the ancient Person, who brings to dissolution the fourteen worlds together with four-faced Brahmā and the rest, and then remains, shining with Kamalā alone."',
        '0.10': '"From prakṛti of three guṇas this Lord brought forth mahat; from it the threefold ego; from that the gods and the senses; then the five elements; from them the sphere of the cosmic egg; and here He created the worlds."',
        '0.11': '"Brahmā, Vāyu, Garuḍa, Indra, Śiva and the other lords and Prajāpatis, the gods and their attendants, men, demons and the rest — He ever creates, sustains and destroys them, and leads each to its own destiny, in play."',
        '0.12': '"With hosts of countless virtues and free of every fault, holding all things in His own power not figuratively but in truth, He takes many forms so that His own may be freed through remembering, praising and bowing to Him."',
        '0.13': '"This lord of the gods once gave the four Vedas to four-faced Brahmā, after slaying, in His horse-headed form (Hayagrīva), the ancient enemy of the good who had stolen the Veda."',
        '0.14': '"As the Boar He lifted up the earth, which had sunk into the waters when dragged by the mighty arms of Indra\'s foe (Hiraṇyākṣa); and as the Tortoise in the billowing ocean He protected His own."',
        '0.15': '"As Narasiṃha, breaker of the fears of His beloved devotees, He tore apart in an instant, with the blazing discs of His claws, His fierce and mighty enemy at the height of His wrath."',
        '0.16': '"As Vāmana, charming in His boyhood, He delighted the demons with His brilliance; by a stratagem He brought low Bali, foe of Indra, and gave the supreme station to His own."',
        '0.17': '"They tell again and again of Him as Paraśurāma, born in the line of great sages of mighty power, who with the gleam of His axe struck down the darkness that was the arrogant kings — like a second sun, for the good of the worlds."',
        '0.18': '(From here the poet tells the lives of Rāma and Kṛṣṇa together through double meanings.) "That compassionate Lord, giver of joy to Vasudeva (also: to the gods), was born of old in the lunar line (also: the solar line); His father on earth was a slayer of foes — Daśaratha, conqueror of the quarters, of formidable might."',
        '0.19': '"Śeṣa, lord of serpents, dear to the Lord of the world, was born too; and they call the lovely one who outshines the moon in beauty, the elder brother, by the name Rāma (Balarāma in the Kṛṣṇa story; in the Rāma story, Lakṣmaṇa\'s elder, Rāma himself)."',
        '0.20': '"Then the Lord, gazed at again and again by His father, who could not bear to part with Him, was taken to the forest by an ascetic fearful of the wicked (Viśvāmitra; also: to Vraja, away from Kaṃsa); there He slew a demoness of the night (Tāṭakā; also: Pūtanā)."',
        '0.21': '"Then the hosts of gods and the good rejoiced in Him as He destroyed the wicked who had made enmity against the sages\' sacrifices — Subāhu raising his arms in battle (in the Rāma story), and the cruel Keśī, Ariṣṭa and the rest (in the Kṛṣṇa story)."',
        '0.22': '"Roaming the woods, bright with birds singing His praises (also: with brāhmaṇas chanting at sacrifices), dear to all of Gokula, He delighted in cherishing the lovely maidens (the gopīs) whose minds and words were moist with love free of worldly desire."',
        '0.23': '"With His brother and all His companions He went to the sweet city dear to His father (Mathurā; also: Mithilā, the city of Janaka); entering it, He, the one beauty of the world, became a festival for the eyes of men and women."',
        '0.24': '"Then, playfully breaking the great bow of Śiva (also: Kaṃsa\'s bow), He crushed the might of King Ugrasena\'s son (Kaṃsa); serving His brāhmaṇa guru, the teacher of lotus-born Brahmā delighted His people with His boundless radiance."',
        '0.25': '"He won the king\'s daughter (Sītā; also: Rukmiṇī) — Kamalā herself, lotus-eyed, come down to earth; defeating hostile kings in His play, He rejoiced and reached His city, hard for foes to approach as the ocean."',
        '0.26': '"To satisfy His mothers\' wishes He went swiftly to the forest, fulfilling what the good desired, together with His auspicious wife and with Lakṣmaṇa, His foremost friend, bearer of the great banner of victory."',
        '0.27': '"Crossing fastnesses led by mountains, He slew many enemies of the good — Khara, Dūṣaṇa and others — and in due course sent to the great darkness of hell (also: slew the demon Naraka) the unbearable terror of the world."',
        '0.28': '"Together with His beloved, honoured by the world, whose splendour graced the lovely hermitage courtyard, the Beloved reached His home — He who carried off the gods\' Pārijāta tree, confounding the pride and heedlessness of its owners."',
        '0.29': '"The Lord chose to let the hateful one — terror to others, who had again and again conquered the guardians of the ten quarters and the circles of kings (Rāvaṇa) — carry off His dearest Śrī, who shone forth here."',
        '0.30': '"Saluted by Hanumān, son of Vāyu, and others, He struck down Indra\'s son (Vālin) with His arrow, and gave the kingdom, cleared of foes, to His dear friend Sugrīva, son of the Sun."',
        '0.31': '"Rejoicing at the great news of His beloved brought from the mouth of Vāyu\'s son, the slayer of Madhu, shining with His fierce host of monkeys (also: with His sharp discus), went to the city in the midst of the ocean, peopled by rākṣasas (also: Dvārakā, peopled by the good)."',
        '0.32': '"With a wheel of sharp arrows (also: His sharp discus) displaying His prowess, the Lord destroyed the vast host that burdened the earth — the arrogant Kumbhakarṇa, huge as a king of elephants (also: the elephant Kuvalayāpīḍa), with his brother and the foe of Indra."',
        '0.33': '"Then, with His wife who had entered the fire, and with His brothers going before Him, this giver of desires to the good returned at last to His abode and attained supreme oneness with His own original form."',
        '0.34': '"He whose feet are worshipped as Mahidāsa was born (as Kalki) of the renowned, pure-souled brāhmaṇa Viṣṇuyaśas; to quell the world\'s sins He bears a sword of great splendour and upholds the radiant Vedic word."',
        '0.35': '"This king of the gods became the son (Kapila) of Manu\'s daughter Devahūti by the sinless Kardama, radiant with austerity; and in time He awakened good souls brimming with devotion to Him."',
        '0.36': '"Taking the form of a most lovely woman (Mohinī), her full youthful beauty manifest, He, the foe of the demons, gave the nectar to the host of the gods."',
        '0.37': '"This Eternal One, who grants the good their station and bestows purity of soul, became a tender child (Dattātreya), lovingly borne by pure-minded Anasūyā, wife of the best of sages, Atri."',
        '0.38': '"As Ṛṣabha, dear to the good, a ruler of the earth, He bore a body with the marks of a paramahaṃsa and wandered free of all ties, worshipped by Sanaka and others who sought the highest truth."',
        '0.39': '"This Hari was born as a son of Dharma, brother of Nara, of noble valour; and to delight the good, His brother called Kṛṣṇa was born of Himself as well."',
        '0.40': '"Salutations, salutations to the Supreme Self — ever one in form, yet of ten forms and of hundreds of thousands of forms, changeless, plainly of infinite forms, every one of His bodies made of bliss and consciousness."',
        '0.41': 'Reflecting thus, his heart full, he bowed with love to Hari and was honoured by Him; and he sat down before the two Unconquered Ones, who, having honoured each other, had taken their seats side by side.',
        '0.42': 'After various conversations there, the Lord of the worlds (Nārāyaṇa), looking at the lovely face of the sage\'s son (Vyāsa), spoke these words in private to the great Ānandatīrtha, who bowed before Him.',
        '0.43': '"Listen, steadfast one, mindful of the gods\' purpose, to what I now say, approved by the noble: your incarnation, now in its youth, will bear great fruit by accomplishing what is all but impossible for others."',
        '0.44': '"Hiding the heart of the sūtras, so dear to the good, and now composing commentaries as they please, others — corrupters of the true sense of Śruti and Smṛti — have struck down true knowledge, and it has all but vanished."',
        '0.45': '"To undo this wrong done by the wicked and to lead your own people back to the good path, compose a commentary on the sūtras without delay; and, O wise poet, harmonize Śruti and Smṛti with the true doctrine."',
        '0.46': 'Hearing these words of the world-teacher, few yet of measureless meaning, the best of speakers, his heart full and unable to bear separation from those two lords of all that moves and is still, then said to them:',
        '0.47': '"Lord, grant me the grace to plunge henceforth into the nectar of constant service to you both; in all three worlds I could find no joy so dear — the one blessing of the world."',
        '0.48': '"On this earth, where the virtues are devoured by the Kali age, there is surely no good person now with a fitting mind; and to describe the Supreme Truth to the unfit is condemned, like offering the sacred oblation to a dog."',
        '0.49': 'To him who spoke so, the Lord said: "Gentle one, there are people on earth worthy of virtue; like fine gems lying unstrung, gather and purify them with compassion through your pure words (also: rays)."',
        '0.50': '"By My supreme command your fame shall ceaselessly bring utmost distress to the wicked, as sunlight to owls, and awaken the good, as it opens the lotus-pools."',
        '0.51': 'Thus that clear speech, flowing for the world\'s happiness from the mouth of the Bearer of the Earth (as a river flows from a mountain), entered the ocean of Madhva\'s vast intellect, already brimming like the sea under the moon\'s rays.',
        '0.52': 'Understanding the honoured will of those two great ones and saying, "So be it," the steady-minded one bowed and placed upon his head their command, which none other could bear.',
        '0.53': 'Like the three Vedas revealing the truth, like the three sacred fires destroying people\'s sins, or like the three worlds that uphold all — the three, Vyāsa the sage\'s son, Nārāyaṇa the son of Dharma, and Madhva, shone there in bliss.',
        '0.54': 'Thus ends the eighth canto, marked with the word "ānanda," of the great poem Śrīmat Sumadhva Vijaya, composed by Nārāyaṇa Paṇḍitācārya, son of Trivikrama Paṇḍitācārya, the ornament of the family of poets.',
      },
    },
  },
};
